import sys

def main():
    import sys
    u, v = map(int, sys.stdin.read().strip().split())
    if u == 0 and v == 0:
        print(0)
        return
    if u > v:
        print(-1)
        return
    n = 1
    while (1 << n) - 1 < u:
        n += 1
    if (1 << n) - 1 + (v - u) < u:
        print(-1)
        return
    result = []
    for i in range(n):
        if u & (1 << i):
            result.append(1 << i)
    remaining_sum = v - u
    if remaining_sum > 0:
        result.append(remaining_sum)
    print(len(result))
    print(' '.join(map(str, result)))

main()
